on conflict (date,platform,account_id,campaign_id) do update set impressions=excluded.impressions,clicks=excluded.clicks,cost=excluded.cost,attributed_sales=excluded.attributed_sales,attributed_orders=excluded.attributed_orders,synced_at=now();

on conflict (date,product_title,variant_title) do update set gross_sales=excluded.gross_sales,net_sales=excluded.net_sales,synced_at=now();

on conflict (date) do update set gross_sales=excluded.gross_sales,refunds=excluded.refunds,net_sales=excluded.net_sales,orders=excluded.orders,units=excluded.units,synced_at=now();

on conflict (account_id,title) do update set severity=excluded.severity,synced_at=now();

on conflict (account_id,product_title) do update set destination_status=excluded.destination_status,synced_at=now();

